import json
import re

data = json.load(open('/app/resources/treasury_bulletin_2020_12.json'))
elements = data.get('document', {}).get('elements', [])
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        content = el.get('content', '')
        if 'Department of Commerce' in content and 'Department of Defense' in content:
            # Extract Commerce column (column 4)
            # Find all table rows
            rows = re.findall(r'<tr>.*?</tr>', content)
            for row in rows:
                if 'Department of Commerce' in row:
                    continue
                # Check if it has Commerce data
                cols = re.findall(r'<td>(.*?)</td>', row)
                if len(cols) >= 5:
                    print(cols)
            break"

